import React from "react";
import FloatButtonChildren from "./FloatButtonChildren";
import { Icon } from "@traveloka/soya-components";

import * as style from "./FloatButton.styles";

class FloatButton extends React.Component {
  constructor(props) {
    super(props);
    this.state = { showChildren: false };
  }

  handleClick = () => {
    const show = this.state.showChildren;
    this.setState({ showChildren: !show });
  };

  getFloatButtonChildren() {
    const { actions } = this.props;
    const result = [];
    for (const i in actions) {
      result.push(
        <li className={style.listButtonChildren} key={i}>
          <FloatButtonChildren
            text={actions[i].text}
            icon={actions[i].icon}
            onClick={actions[i].handleClick}
          />
        </li>
      );
    }
    return result;
  }

  render() {
    const children = this.getFloatButtonChildren();
    return (
      <div>
        <div className={style.float} onClick={this.handleClick}>
          <div className={style.mainFloatIcon}>
            <Icon icon="view-list" />
          </div>
        </div>
        <ul
          className={style.listIcon}
          style={{ visibility: this.state.showChildren ? "visible" : "hidden" }}
        >
          {children}
        </ul>
      </div>
    );
  }
}

export default FloatButton;
